using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must preserve it.
            entity.HasDiscriminator().HasValue("Blog");
            entity.Property<string>("$type").ToJsonProperty("Discriminator");

            // Breaking change 2: EF Core 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|1" format, so we must opt back in.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();

            // Breaking change 3: Cosmos DB does not support indexes defined via EF Core.
            // HasIndex() now throws by default in 9.0. Removed.
        });

        // Opt into sync I/O — SaveChanges() (non-async) now throws by default in 9.0.
        // Breaking change 4: Use SaveChangesAsync or configure this.
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Breaking change 4 fix: Allow synchronous I/O for legacy code paths.
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "BlogDb",
            cosmosOptions => { });
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

